Mesh<Point, double> mesh;
    auto edges = rt.finite_edges();
    std::map<typename RT::Vertex_handle, std::vector<typename RT::Cell_handle>> vertex_to_cells;

    // Build a mapping from vertices to incident cells
    for (auto cell = rt.finite_cells_begin(); cell != rt.finite_cells_end(); ++cell) {
        for (int i = 0; i < 4; ++i) {
            vertex_to_cells[cell->vertex(i)].push_back(cell);
        }
    }

    // Iterate over all edges and collect incident cells
    for (auto edge = edges.begin(); edge != edges.end(); ++edge) {
        typename RT::Vertex_handle v1 = edge->first->vertex(edge->second);
        typename RT::Vertex_handle v2 = edge->first->vertex(edge->third);
        double edge_length = std::sqrt(rt.segment(edge).squared_length());

        if (edge_length > threshold) {
            std::vector<typename RT::Cell_handle> incident_cells;
            std::set<typename RT::Cell_handle> unique_cells;

            // Collect incident cells from both vertices
            for (auto cell : vertex_to_cells[v1]) {
                if (cell->has_vertex(v2)) {
                    unique_cells.insert(cell);
                }
            }
            for (auto cell : vertex_to_cells[v2]) {
                if (cell->has_vertex(v1)) {
                    unique_cells.insert(cell);
                }
            }

            // Convert to vector
            incident_cells.assign(unique_cells.begin(), unique_cells.end());

            // Create polygon from incident cells
            if (incident_cells.size() >= 3) {
                std::vector<Point> polygon;
                for (auto cell : incident_cells) {
                    // Find the dual point (power diagram vertex) for the cell
                    Point dual = rt.dual(cell);
                    polygon.push_back(dual);
                }

                // Add face to mesh
                mesh.add_face(polygon);

                // Store edge length as face property
                mesh.face_property(mesh.faces().back()) = edge_length;
            }
        }
    }

    return mesh;
// END_CODE

